    "DNA": ["DNA", "gene", "genome", "sequence", "chromosome", "base pair", "double helix", "PCR", "genetic", "genomics"],
    "music_history": ["music", "history", "baroque", "classical", "romantic", "jazz", "rock", "symphony", "opera", "composer", "melody", "harmony"]
}

def extract_text_pdf(filepath):
    text = ""
    try:
        reader = PdfReader(filepath)
        for page in reader.pages:
            text += page.extract_text() or ""
    except Exception as e:
        print(f"Error extracting text from PDF {filepath}: {e}")
    return text.lower()

def extract_text_docx(filepath):
    text = ""
    try:
        doc = docx.Document(filepath)
        for para in doc.paragraphs:
            text += para.text + "\n"
    except Exception as e:
        print(f"Error extracting text from DOCX {filepath}: {e}")
    return text.lower()

def extract_text_pptx(filepath):
    text = ""
    try:
        prs = pptx.Presentation(filepath)
        for slide in prs.slides:
            for shape in slide.shapes:
                if hasattr(shape, "text"):
                    text += shape.text + "\n"
    except Exception as e:
        print(f"Error extracting text from PPTX {filepath}: {e}")
    return text.lower()

def classify_text(text):
    scores = {subject: 0 for subject in subjects}
    for subject, keywords in subjects.items():
        for kw in keywords:
            if kw in text:
                scores[subject] += 1
    # Return subject with highest score; if tie, pick first
    max_score = max(scores.values())
    if max_score == 0:
        # No matches, default to LLM? But we need to assign to one subject.
